interface LanguageContextValue {
    language: Language;
    setLanguage: (language: Language) => void;
    t: (text: string) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);
const STORAGE_KEY = "phrolova-language";

function readLanguage(): Language {
    try {
        const value = localStorage.getItem(STORAGE_KEY);
        return value === "en" || value === "ja" || value === "ko" ? value : "ko";
    } catch {
        return "ko";
    }
}

export function LanguageProvider({ children }: { children: ReactNode }) {
    const [language, setLanguageState] = useState<Language>(readLanguage);

    const setLanguage = (next: Language) => {
        setLanguageState(next);
        try { localStorage.setItem(STORAGE_KEY, next); } catch { /* Preferences may be unavailable in private mode. */ }
    };

    useEffect(() => {
        document.documentElement.lang = language;
    }, [language]);

    const value = useMemo<LanguageContextValue>(() => ({
        language,
        setLanguage,
        t: (text) => language === "ko" ? text : messages[language][text] ?? text,
    }), [language]);

    return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
    const value = useContext(LanguageContext);
    if (!value) throw new Error("useLanguage must be used inside LanguageProvider");
    return value;
}
